// HTTP Parser (350줄)
// HTTP/1.1 요청 파싱

struct HttpRequest {
  method: string,
  path: string,
  version: string,
  headers: map<string, string>,
  body: array<u8>,
  body_len: i32,
}

enum ParseError {
  InvalidRequestLine,
  InvalidHeaders,
  InvalidBody,
  MissingContentLength,
  ToolargePayload,
}

fn parse_request(raw: array<u8>) -> Result<HttpRequest, ParseError>
  intent "raw 바이트를 HttpRequest로 파싱"
  do
    // 1. CRLF(\r\n)로 라인 분할
    let lines = split_by_crlf(raw)

    if length(lines) < 1
      return Err(InvalidRequestLine)

    // 2. Request Line 파싱
    match parse_request_line(lines[0])
      Ok((method, path, version)) => {
        // 3. Headers 파싱
        match parse_headers_section(lines, 1)
          Ok((headers, body_start)) => {
            // 4. Content-Length 추출
            let content_len = match get_header(headers, "Content-Length")
              Some(len_str) => parse_int_safe(len_str),
              None => 0
            end

            // 5. Body 추출
            let body = extract_body(raw, body_start, content_len)

            // 6. Payload 크기 검증 (1MB limit)
            if content_len > 1048576
              return Err(ToolargePayload)

            return Ok({
              method: method,
              path: path,
              version: version,
              headers: headers,
              body: body,
              body_len: content_len,
            })
          }
          Err(e) => return Err(e)
        end
      }

// HTTP Handler (200줄)
// HTTP 응답 생성

struct HttpResponse {
  version: string,
  status: i32,
  reason: string,
  headers: map<string, string>,
  body: array<u8>,
}

fn build_response(
  status: i32,
  headers: map<string, string>,
  body: array<u8>
) -> HttpResponse
  intent "HttpResponse 구조체 생성"
  do
    return {
      version: "HTTP/1.1",
      status: status,
      reason: status_code_to_reason(status),
      headers: headers,
      body: body,
    }
end

fn serialize_response(resp: HttpResponse) -> array<u8>
  intent "HttpResponse를 바이트 배열로 변환"
  do
    // 1. Status Line
    let status_line = serialize_status_line(resp.version, resp.status, resp.reason)

    // 2. Headers
    let headers_bytes = serialize_headers(resp.headers)

    // 3. CRLF 분리
    let separator = string_to_bytes("\r\n")

    // 4. Body
    let body_bytes = resp.body

    // 5. 연결
    let result = concat_bytes(concat_bytes(concat_bytes(status_line, separator), headers_bytes), body_bytes)
    return result
end

fn serialize_status_line(version: string, status: i32, reason: string) -> array<u8>
  intent "상태 라인 생성: 'HTTP/1.1 200 OK\\r\\n'"
  do
    let line = version + " " + int_to_string(status) + " " + reason + "\r\n"
    return string_to_bytes(line)
end

